import type { FilterDataStructure, FilterForm } from 'models/Filters';

import { getInnovationHubGeoLabel } from '../../../utils/getInnovationHubGeoLabel';
import { getPerformanceAndBreakdownBrandLabel } from './getPerformanceAndBreakdownBrandLabel';

export function getPerformanceAndBreakdownTitleScope(
  dataFilters: FilterDataStructure,
  applied: FilterForm,
): string {
  const geoLabel = getInnovationHubGeoLabel(dataFilters, applied).trim();
  const brandLabel = getPerformanceAndBreakdownBrandLabel(
    dataFilters,
    applied,
  ).trim();

  return [geoLabel, brandLabel].filter(Boolean).join(' ');
}
